ev('war','ธงรบบนเนินตะวันตก','ความขัดแย้งใน{kingdom}มาถึงหมู่บ้าน คนในตลาดเริ่มเลือกข้าง ขณะที่ผู้อพยพต้องการเพียงที่นอน',[ch('คุ้มกันขบวนผู้อพยพ','พลัง +10 • ชื่อเสียง +9 • เสี่ยง',{power:10,fame:9,flag:'refugees'},'เด็กคนหนึ่งมอบตุ๊กตาให้คุณแทนคำขอบคุณ',.3,'คุณได้รับบาดเจ็บระหว่างคุ้มกัน'),ch('เปิดครัวกลาง','ทอง −18 • สายสัมพันธ์ +12',{gold:-18,bond:12,fame:5},'กลิ่นข้าวร้อนทำให้ผู้คนวางอาวุธชั่วคราว'),ch('เจรจากับทั้งสองฝ่าย','ปัญญา +10 • ชื่อเสียง +8',{wisdom:10,fame:8,flag:'peace'},'ทั้งสองฝ่ายยอมให้ขบวนเสบียงผ่าน',.2,'ข้อเสนอถูกปฏิเสธ แต่ยังมีคนรับฟัง'),ch('พาครอบครัวหนีออกจากนคร','ทอง −10 • สุขภาพ +8',{gold:-10,health:8,bond:5},'คุณเลือกให้ทุกคนมีวันพรุ่งนี้')],22);
ev('demon','ตลาดพันธสัญญา','พ่อค้าปีศาจเสนอมนุษย์ผู้ติดพันธะเป็นบริวารตามธรรมเนียมของนคร เขาก้มหน้าแต่กำกุญแจดอกเล็กไว้แน่น',[ch('จ่ายเพื่อปลดพันธะให้เขา','ทอง −25 • สายสัมพันธ์ +12',{gold:-25,bond:12,flag:'freed'},'เมื่อได้รับอิสระ เขาขอร่วมเดินทางในฐานะสหาย'),ch('รับเป็นบริวารและคุ้มครอง','ทอง −15 • ได้ผู้ติดตาม',{gold:-15,retainer:true,bond:3},'เขายอมร่วมทาง ภายใต้ข้อตกลงที่ขอทบทวนได้'),ch('ท้าทายกฎหมายพันธสัญญา','ปัญญา +12 • ชื่อเสียง +8 • เสี่ยง',{wisdom:12,fame:8,flag:'reform'},'คุณพบช่องโหว่ในกฎหมายเก่า',.3,'สภาปฏิเสธคำร้องของคุณ')],18,{demon:true});
ev('petquest','เสียงเรียกที่มีเพียงมันได้ยิน','{pet}ของคุณหยุดตรงประตูปิดตาย มันถือใบไม้สีเงินและมองกลับมาราวกับอยากให้คุณเชื่อใจ',[ch('ตามมันไปหลังประตู','เวท +10 • ผูกพันสัตว์เลี้ยง +15',{magic:10,petBond:15,flag:'petdoor'},'คุณพบสวนที่สัตว์วิเศษใช้รักษาบาดแผล',.15,'ทางเดินพังลง คุณอุ้มมันกลับอย่างปลอดภัย'),ch('รอมันอยู่ตรงนี้','ความสุข +8 • ผูกพัน +10',{joy:8,petBond:10},'มันกลับมาพร้อมเมล็ดพันธุ์ให้คุณ'),ch('ชวนผู้เชี่ยวชาญมาช่วย','ปัญญา +9 • ผูกพัน +8',{wisdom:9,petBond:8},'ประตูกลายเป็นเขตคุ้มครองสัตว์เวท')],14,{needsPet:true});
ev('bookreturn','หน้าสุดท้ายของหนังสือที่มีชีวิต','หนังสือจากวัยเด็กกลับมาเปิดเอง มันขอให้คุณเขียนตอนจบ ก่อนที่ผู้เขียนคนเก่าจะหายไป',[ch('เขียนเรื่องของคนธรรมดา','ปัญญา +14 • ความสุข +8',{wisdom:14,joy:8,fame:6},'หนังสือร้องไห้เป็นหมึกสีทอง'),ch('เขียนคาถาปลดปล่อยผู้เขียน','เวท +18 • เสี่ยง',{magic:18,fame:8},'ผู้เขียนก้าวออกมาขอบคุณคุณ',.25,'หน้ากระดาษขาด แต่คุณช่วยความทรงจำไว้ได้'),ch('ส่งต่อให้เด็กที่รักการอ่าน','สายสัมพันธ์ +14',{bond:14,fame:5},'เรื่องราวยังไม่ต้องจบในมือคุณ')],25,{requires:'book'});
ev('heirreturn','บัลลังก์ที่เว้นไว้ให้คุณ','หลักฐานสายเลือดของคุณถูกเปิดเผย สภาเสนอตำแหน่งแลกกับการละทิ้งผู้คนที่ไม่คู่ควรกับตระกูล',[ch('รับตำแหน่งแล้วเปลี่ยนกฎ','ชื่อเสียง +20 • สายสัมพันธ์ −8',{fame:20,bond:-8,gold:40,flag:'crown'},'ชื่อคุณปรากฏบนกฎหมายฉบับใหม่',.25,'ขุนนางขัดขวางจนคุณต้องถอย'),ch('ปฏิเสธต่อหน้าสภา','สายสัมพันธ์ +15 • ความสุข +12',{bond:15,joy:12},'ผู้คนหน้าประตูปราสาทปรบมือให้คุณ'),ch('เปลี่ยนมรดกเป็นทุนสาธารณะ','ทอง −20 • ชื่อเสียง +18',{gold:-20,fame:18,wisdom:8},'ตราตระกูลกลายเป็นตราของห้องสมุด')],28,{requires:'heir'});
ev('oldfriend','สัญญาจากลานหมู่บ้าน','เพื่อนที่เคยถูกกีดกันกลับมา เขาเป็นผู้นำชุมชนต่างเผ่า และต้องการคนร่วมสร้างบ้านที่ไม่มีกำแพง',[ch('ร่วมก่อตั้งเมืองเสรี','ทอง −25 • ชื่อเสียง +20',{gold:-25,fame:20,bond:12,flag:'freecity'},'เด็กหลายเผ่าเล่นด้วยกันในลานแห่งใหม่'),ch('ให้คำปรึกษาโดยไม่ย้ายบ้าน','ปัญญา +12 • สายสัมพันธ์ +8',{wisdom:12,bond:8},'ระยะทางไม่ทำให้คำสัญญาห่างไกล'),ch('ช่วยหาเสบียงให้ชุมชน','ทอง −12 • สายสัมพันธ์ +14',{gold:-12,bond:14},'เขายังเก็บของเล่นในวันนั้นไว้')],30,{requires:'friend'});
ev('family','บ้านที่มีที่ว่างอีกหนึ่งคน','มีเด็กไร้ครอบครัวเผ่าอื่นมาขอหลบฝนใต้ชายคาคุณ เขาถามว่า คืนนี้ขออยู่ด้วยได้ไหม',[ch('รับเป็นครอบครัว','ทอง −18 • มีลูกบุญธรรม',{gold:-18,bond:15,child:true},'บ้านของคุณมีรองเท้าคู่เล็กเพิ่มขึ้น'),ch('ช่วยตามหาครอบครัวเดิม','ปัญญา +10 • สายสัมพันธ์ +8',{wisdom:10,bond:8},'ญาติที่ตามหากันมานานได้พบกัน'),ch('ประสานวิหารให้ดูแล','ทอง −5 • ชื่อเสียง +8',{gold:-5,fame:8},'คุณกลับไปเยี่ยมเขาเป็นประจำ')],24);
ev('illness','วันที่ร่างกายขอให้หยุด','มือที่เคยมั่นคงเริ่มสั่น ผู้รักษาบอกว่าคุณใช้ชีวิตรวดเร็วเกินไป แม้ความฝันยังเหลืออีกมาก',[ch('พักและรับการรักษา','ทอง −20 • สุขภาพ +24',{gold:-20,health:24,joy:5},'คุณได้เรียนรู้จังหวะของการไม่ทำอะไร'),ch('ศึกษาสมุนไพรด้วยตัวเอง','ปัญญา +10 • สุขภาพ +12',{wisdom:10,health:12},'ชาถ้วยขมช่วยให้คุณหลับได้อีกครั้ง'),ch('ทำงานต่อเท่าที่ทำไหว','ทอง +15 • สุขภาพ −8',{gold:15,health:-8},'งานเสร็จ แต่คุณต้องยอมลดความเร็ว')],35);
ev('legacy','ศิษย์ที่ถามคำถามยากที่สุด','{npc}ถามว่าความสำเร็จที่แท้จริงคืออะไร คุณนึกถึงทุกการตัดสินใจที่ผ่านมาและยังไม่มีคำตอบเดียว',[ch('สอนสิ่งที่เคยทำพลาด','ปัญญา +12 • สายสัมพันธ์ +8',{wisdom:12,bond:8,flag:'mentor'},'ศิษย์กล้าลองสิ่งที่คุณไม่เคยกล้า'),ch('ร่วมออกเดินทางครั้งใหม่','พลัง +10 • ความสุข +10',{power:10,joy:10},'โลกยังมีที่ที่คุณไม่รู้จัก'),ch('เขียนบันทึกส่งต่อ','ชื่อเสียง +12 • ปัญญา +8',{fame:12,wisdom:8,flag:'memoir'},'เรื่องของคุณกลายเป็นหนังสือบนโต๊ะใครสักคน')],45);
ev('lastgarden','สวนในวันที่แสงอ่อนลง','คุณนั่งมองแสงลอดใบไม้ {petline} เรื่องมากมายที่เคยเร่งรีบดูอ่อนโยนขึ้นในวันนี้',[ch('เล่าเรื่องให้คนรุ่นหลังฟัง','สายสัมพันธ์ +12 • ความสุข +10',{bond:12,joy:10},'ทุกคนฟังจนแสงสุดท้ายลับไป'),ch('เดินไปยังสถานที่โปรด','สุขภาพ +8 • ความสุข +12',{health:8,joy:12},'เส้นทางเดิมมีดอกไม้ที่คุณไม่เคยสังเกต'),ch('เตรียมของขวัญชิ้นสุดท้าย','ทอง −12 • ชื่อเสียง +12',{gold:-12,fame:12},'คุณห่อของขวัญด้วยกระดาษสีฟ้าซีด')],60);
