ev('rainchild','โลกทั้งใบในหน้าต่างบานเล็ก','ฝนตกเหนือ{kingdom} คุณนั่งมองหยดน้ำไหลบนหน้าต่าง ข้างหลังมีคนในบ้านฮัมเพลงเบา ๆ',[ch('ลองฮัมเพลงตาม','สายสัมพันธ์ +7 • ความสุข +5',{bond:7,joy:5},'เสียงอีกเสียงตอบรับเพลงของคุณ'),ch('นับหยดฝนที่ไหลผ่าน','ปัญญา +7',{wisdom:7},'คุณเริ่มมองเห็นรูปแบบในสิ่งเล็ก ๆ'),ch('จับแสงที่สะท้อนในน้ำ','เวท +6 • ความสุข +4',{magic:6,joy:4},'ประกายเล็ก ๆ ยังค้างอยู่บนนิ้ว')],1,{max:8});
ev('childmarket','ทองแรกในฝ่ามือ','ผู้ดูแลให้ทองคุณหนึ่งทองและพาเดินตลาด{kingdom} โลกดูเต็มไปด้วยสิ่งที่อยากได้',[ch('แบ่งซื้อขนมให้คนในบ้าน','สายสัมพันธ์ +8',{bond:8,joy:3},'ขนมชิ้นเล็กถูกแบ่งออกหลายส่วน'),ch('เลือกสมุดเล่มจิ๋ว','ปัญญา +7',{wisdom:7},'หน้ากระดาษแรกมีรูปบ้านของคุณ'),ch('เก็บไว้เป็นเงินออม','ทอง +8',{gold:8},'คุณเริ่มเข้าใจว่าการรอก็เป็นทางเลือก')],3,{max:12});
ev('childfear','เงาใต้เตียง','คุณได้ยินเสียงจากใต้เตียงทุกคืน แต่เมื่อจุดตะเกียงกลับไม่มีสิ่งใดอยู่',[ch('ถามว่าอยากเป็นเพื่อนไหม','สายสัมพันธ์ +6 • เวท +4',{bond:6,magic:4},'เสียงนั้นเป็นภูตหลงทางตัวเล็ก'),ch('เรียกคนในบ้านมาช่วยดู','สายสัมพันธ์ +8',{bond:8,health:3},'คุณนอนหลับโดยมีคนจับมือไว้'),ch('วาดสิ่งที่คิดว่าอยู่ตรงนั้น','ปัญญา +7 • ความสุข +3',{wisdom:7,joy:3},'รูปวาดทำให้สิ่งน่ากลัวดูน่ารักขึ้น')],4,{max:13});
